style.css:
@-moz-document domain("roblox.com") {
/* Chuyển nút Play thành màu đen */
  .btn-primary-play, .game-home-play-button {
    background-color: #000000 !important; /* Màu đen */
    color: #ffffff !important; /* Chữ màu trắng */
    border: 2px solid #333333 !important; /* Viền xám */
  }

  /* Khi di chuột vào nút Play */
  .btn-primary-play:hover, .game-home-play-button:hover {
    background-color: #222222 !important; /* Màu xám đậm khi hover */
  }

  /* Khi nút bị nhấn */
  .btn-primary-play:active, .game-home-play-button:active {
    background-color: #444444 !important; /* Màu xám sáng hơn khi click */
  }
}
